export type HeaderEventName = "create" | "transfer" | "remove" | "rename";

export interface HeaderEvent {
  name: HeaderEventName;
  title: string;
}

export type HeaderListener = (event: HeaderEvent) => void;

const eventNames: readonly HeaderEventName[] = ["create", "transfer", "remove", "rename"];

export class PanelHeaderController {
  private readonly listeners = new Map<HeaderEventName, HeaderListener[]>();

  constructor(private readonly title: string) {
    if (typeof title !== "string" || title.trim() === "") throw new TypeError("title must be nonblank");
    for (const name of eventNames) this.listeners.set(name, []);
  }

  on(name: HeaderEventName, listener: HeaderListener): () => void {
    if (!eventNames.includes(name)) throw new TypeError("invalid event name");
    if (typeof listener !== "function") throw new TypeError("listener must be a function");
    const bucket = this.listeners.get(name)!;
    const registration = listener;
    bucket.push(registration);
    return () => {
      const index = bucket.indexOf(registration);
      bucket.splice(index, 1);
    };
  }

  private emit(name: HeaderEventName): void {
    const event: HeaderEvent = { name, title: this.title };
    for (const listener of [...this.listeners.get(name)!]) listener(event);
  }

  create(): void { this.emit("create"); }
  transfer(): void { this.emit("transfer"); }
  remove(): void { this.emit("remove"); }
  rename(): void { this.emit("rename"); }
}

