import { PanelHeaderController } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  assert(JSON.stringify(actual) === JSON.stringify(expected), `${message}: ${JSON.stringify(actual)}`);
}
function throwsTypeError(action: () => void, message: string): void {
  let error: unknown;
  try { action(); } catch (caught) { error = caught; }
  assert(error instanceof TypeError, message);
}

throwsTypeError(() => new PanelHeaderController('   '), 'blank title rejected');
const controller = new PanelHeaderController('  Current Title  ');
const received: any[] = [];
const listener = (event: any): void => { received.push(event); };
const unsubscribeFirst = controller.on('create', listener);
controller.on('create', listener);
controller.create();
equal(received, [
  { name: 'create', title: '  Current Title  ' },
  { name: 'create', title: '  Current Title  ' },
], 'duplicate registrations and unchanged title');
unsubscribeFirst();
unsubscribeFirst();
controller.create();
assert(received.length === 3, 'idempotent unsubscribe removes one registration');

const snapshot = new PanelHeaderController('Panel');
const calls: string[] = [];
let removeSecond = (): void => {};
snapshot.on('rename', () => {
  calls.push('first');
  removeSecond();
  snapshot.on('rename', () => calls.push('late'));
});
removeSecond = snapshot.on('rename', () => calls.push('second'));
snapshot.rename();
equal(calls, ['first', 'second'], 'first emission uses snapshot');
snapshot.rename();
equal(calls, ['first', 'second', 'first', 'late'], 'changes affect later emission');

const names: string[] = [];
const all = new PanelHeaderController('X');
for (const name of ['create', 'transfer', 'remove', 'rename'] as const) {
  all.on(name, (event) => names.push(`${event.name}:${event.title}`));
}
all.create(); all.transfer(); all.remove(); all.rename();
equal(names, ['create:X', 'transfer:X', 'remove:X', 'rename:X'], 'event methods');

throwsTypeError(() => all.on('other' as any, () => {}), 'invalid name rejected');
throwsTypeError(() => all.on('create', 4 as any), 'non-function rejected');
const failure = new Error('stop');
let after = false;
all.on('transfer', () => { throw failure; });
all.on('transfer', () => { after = true; });
let caught: unknown;
try { all.transfer(); } catch (error) { caught = error; }
assert(caught === failure && !after, 'exceptions propagate immediately');

